13	
14		@Test
15		void coreCustomerCodesStayUnique() throws Exception {
16			String c1 = fetchOwner(createOwnerOk(withPostcode(ownerNode()))).get("customerCode").asText();
17			String c2 = fetchOwner(createOwnerOk(withPostcode(ownerNode()))).get("customerCode").asText();
18			assertNotEquals(c1, c2);
19		}
20	}
