274	    /**
275	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
276	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
277	     *
278	     * @param fields the submitted owner fields
279	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
280	     *                                        {@code null} or blank, or if address is blank after
281	     *                                        normalization
282	     */
283	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
284	        List<String> missing = new ArrayList<>();
285	        if (isBlank(fields.getFirstName())) {
286	            missing.add("firstName");
287	        }
288	        if (isBlank(fields.getLastName())) {
289	            missing.add("lastName");
290	        }
