309	    /**
310	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
311	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
312	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
313	     */
314	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
315	        "NSW", new int[] {2000, 2099},
316	        "VIC", new int[] {3000, 3099},
317	        "QLD", new int[] {4000, 4099});
318	
319	    /**
320	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
321	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
322	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
323	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
324	     *
325	     * @param postcode the submitted postcode, or {@code null} when omitted
326	     * @param city the owner's city, used to derive the region whose range constrains the postcode
327	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
328	     *                                  city's region
329	     */
330	    private void validatePostcode(String postcode, String city) {
331	        if (postcode == null) {
332	            return;
333	        }
334	        if (!postcode.matches("[0-9]{4}")) {
335	            throw new InvalidPostcodeException(postcode);
336	        }
337	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
338	        if (range == null) {
339	            return;
340	        }
341	        int value = Integer.parseInt(postcode);
342	        if (value < range[0] || value > range[1]) {
343	            throw new InvalidPostcodeException(postcode);
344	        }
345	    }
346	
347	    /**
348	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
349	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
350	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
351	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
352	     * <p>
353	     * Where a per-country rule is defined the national-number length is validated against the country
354	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
355	     * requires exactly 10.
356	     *
357	     * @param telephone the raw telephone value from the request
358	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
359	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
360	     */
361	    private String normalizeTelephone(String telephone) {
362	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
363	        String digits;
364	        if (cleaned.startsWith("+")) {
365	            digits = cleaned.substring(1);
366	        } else {
367	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
368	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
369	            digits = "61" + national;
370	        }
371	        if (!digits.matches("[0-9]{8,15}")) {
372	            throw new InvalidTelephoneException(cleaned);
373	        }
374	        // Validate the national-number length against the country code where a rule is defined.
375	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
376	            throw new InvalidTelephoneException(cleaned);
377	        }
378	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
379	            throw new InvalidTelephoneException(cleaned);
380	        }
381	        return "+" + digits;
382	    }
383	
384	    /**
385	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
386	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
387	     * lower-cased.
388	     *
389	     * @param email the raw email value from the request, or {@code null} if omitted
390	     * @return the lower-cased email, or {@code null} if none was supplied
391	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
392	     */
393	    private String normalizeEmail(String email) {
394	        if (email == null) {
395	            return null;
396	        }
397	        String trimmed = email.strip();
398	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
399	            throw new InvalidEmailException(email);
400	        }
401	        String normalized = trimmed.toLowerCase(Locale.ROOT);
402	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
403	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
404	            throw new DisposableEmailDomainException(domain);
405	        }
406	        return normalized;
407	    }
408	
409	    /**
410	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
411	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
412	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
413	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
414	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
415	     *
416	     * @param address the raw address value from the request (may be {@code null})
417	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
418	     */
419	    private String normalizeAddress(String address) {
420	        if (address == null) {
421	            return "";
422	        }
423	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
424	        if (collapsed.isEmpty()) {
425	            return "";
426	        }
427	        String[] tokens = collapsed.split(" ");
428	        StringBuilder sb = new StringBuilder(collapsed.length());
429	        for (int i = 0; i < tokens.length; i++) {
430	            if (i > 0) {
431	                sb.append(' ');
432	            }
433	            sb.append(expandAddressAbbreviation(tokens[i]));
434	        }
435	        return sb.toString();
436	    }
437	
438	    /**
439	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
440	     * returns the token unchanged when it is not a recognised abbreviation.
441	     *
442	     * @param token an upper-cased whole-word address token
443	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
444	     */
445	    private String expandAddressAbbreviation(String token) {
446	        return switch (token) {
447	            case "ST" -> "STREET";
448	            case "RD" -> "ROAD";
449	            case "AVE" -> "AVENUE";
450	            default -> token;
451	        };
452	    }
