454	    /**
455	     * Builds the customer code assigned to a newly created owner, formatted {@code '<REGION>-<HASH8>'}
456	     * where {@code REGION} is the region derived from the owner's postcode (falling back to the city when
457	     * the postcode resolves to no known region), the same derivation that yields the owner's locality, and
458	     * {@code HASH8} is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
459	     * normalized telephone concatenated with the owner's last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike the
460	     * former per-city sequence, the code is a pure function of the owner's own region and identity, so no
461	     * sequence number is assigned.
462	     *
463	     * @param owner the owner being created, with normalized telephone and postcode already set
464	     * @return the assigned customer code
465	     */
466	    private String generateCustomerCode(Owner owner) {
467	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
468	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
469	            .substring(0, 8).toUpperCase(Locale.ROOT);
470	        return region + "-" + hash8;
471	    }
472	
473	    /**
474	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
475	     *
476	     * @param value the value to hash
477	     * @return the 64-character lower-case hex SHA-256 digest
478	     */
479	    private String sha256Hex(String value) {
480	        try {
481	            byte[] digest = MessageDigest.getInstance("SHA-256")
482	                .digest(value.getBytes(StandardCharsets.UTF_8));
483	            StringBuilder sb = new StringBuilder(digest.length * 2);
484	            for (byte b : digest) {
485	                sb.append(String.format("%02x", b));
486	            }
487	            return sb.toString();
488	        } catch (NoSuchAlgorithmException e) {
489	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
490	        }
491	    }
492	
493	    /**
494	     * Counts how many existing owners already share the given first name and last name, compared
495	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
496	     * owner being created.
497	     *
498	     * @param firstName the first name of the owner being created
499	     * @param lastName the last name of the owner being created
500	     * @return the number of existing owners with the same first and last name (case-insensitively)
501	     */
502	    private int countNamesakes(String firstName, String lastName) {
503	        return (int) this.clinicService.findAllOwners().stream()
504	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
505	                && lastName.equalsIgnoreCase(existing.getLastName()))
506	            .count();
507	    }
