509	    /**
510	     * Computes the size of the owner's household: the number of existing owners already sharing the given
511	     * {@code householdId} plus the owner being created itself. The existing count is taken before the new
512	     * owner is persisted, so adding one for the owner yields the household's total membership including it
513	     * (e.g. two existing members give a household size of 3 for the third member). Households are keyed on
514	     * the deterministic {@code householdId} (derived from last name and postcode).
515	     *
516	     * @param householdId the computed household identifier of the owner being created
517	     * @return the household size including the owner being created (at least 1)
518	     */
519	    private int countHouseholdSize(String householdId) {
520	        long existing = this.clinicService.findAllOwners().stream()
521	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
522	            .count();
523	        return (int) existing + 1;
524	    }
