526	    /**
527	     * The maximum number of owners permitted in a single city. A create request whose city already
528	     * holds this many owners is rejected.
529	     */
530	    private static final int CITY_OWNER_LIMIT = 50;
531	
532	    /**
533	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
534	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
535	     * differing only in the casing of their city share one capacity pool. The count is taken before the
536	     * new owner is persisted, so it excludes the owner being created.
537	     *
538	     * @param city the city of the owner being created
539	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
540	     */
541	    private void rejectCityAtCapacity(String city) {
542	        long existing = this.clinicService.findAllOwners().stream()
543	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
544	            .count();
545	        if (existing >= CITY_OWNER_LIMIT) {
546	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
547	        }
548	    }
549	
550	    /**
551	     * The maximum number of owners permitted to be created in a single day. A create request whose
552	     * registration date already holds this many owners is rejected.
553	     */
554	    private static final int DAILY_OWNER_LIMIT = 100;
555	
556	    /**
557	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
558	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
559	     * persisted, so it excludes the owner being created.
560	     *
561	     * @param registrationDate the registration date of the owner being created
562	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
563	     */
564	    /**
565	     * Adjusts an effective registration date so that it always falls on a business day. When the given
566	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
567	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
568	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
569	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
570	     * business-day-adjusted date.
571	     *
572	     * @param date the effective registration date, supplied or defaulted
573	     * @return the same date when it is a weekday, otherwise the next Monday
574	     */
575	    private LocalDate rollToBusinessDay(LocalDate date) {
576	        DayOfWeek day = date.getDayOfWeek();
577	        if (day == DayOfWeek.SATURDAY) {
578	            return date.plusDays(2);
579	        }
580	        if (day == DayOfWeek.SUNDAY) {
581	            return date.plusDays(1);
582	        }
583	        return date;
584	    }
