586	    /**
587	     * The number of owners that must already exist for a given day before a further create is flagged as a
588	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
589	     * the created owner carries {@code bulkSignupWarning = true}.
590	     */
591	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
592	
593	    /**
594	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
595	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
596	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
597	     * the daily create-limit rule's accumulation path.
598	     *
599	     * @param registrationDate the registration date of the owner being created
600	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
601	     */
602	    private boolean isBulkSignupDay(LocalDate registrationDate) {
603	        long existing = this.clinicService.findAllOwners().stream()
604	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
605	            .count();
606	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
607	    }
