609	    /**
610	     * Rejects a create request whose supplied {@code registrationDate} is later than the server date. A
611	     * registration cannot be dated in the future. The check applies only to a date supplied in the request;
612	     * a {@code null} value (which is later defaulted to the server date) is accepted, and the comparison is
613	     * made against the supplied value before any business-day adjustment.
614	     *
615	     * @param registrationDate the registration date supplied in the request, or {@code null} when omitted
616	     * @throws FutureRegistrationDateException if a supplied registration date is later than the server date
617	     */
618	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
619	        if (registrationDate == null) {
620	            return;
621	        }
622	        LocalDate today = LocalDate.now();
623	        if (registrationDate.isAfter(today)) {
624	            throw new FutureRegistrationDateException(registrationDate, today);
625	        }
626	    }
