628	    private void rejectDailyLimitReached(LocalDate registrationDate) {
629	        long existing = this.clinicService.findAllOwners().stream()
630	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
631	            .count();
632	        if (existing >= DAILY_OWNER_LIMIT) {
633	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
634	        }
635	    }
